function validateVerification(b){const reject=m=>{throw Object.assign(new Error(m),{status:400})};if(b.dummyConfirmed!==true)reject('Confirm that you are submitting dummy documents only.');const info={};for(const [key,max]of [['businessName',100],['ownerName',60],['address',250],['city',80],['businessType',60]]){if(typeof b[key]!=='string'||!b[key].trim()||b[key].length>max)reject('Complete all business details.');info[key]=b[key].trim()}if(typeof b.phone!=='string'||!/^\d{10}$/.test(b.phone))reject('Enter a 10-digit sample phone number.');info.phone=b.phone;if(typeof b.pincode!=='string'||!/^\d{6}$/.test(b.pincode))reject('Enter a 6-digit postal code.');info.pincode=b.pincode;const docs={};for(const key of ['identityDocument','businessDocument']){const d=b[key];if(!d||typeof d.name!=='string'||d.name.length>100||!d.name.toLowerCase().endsWith('.txt')||typeof d.content!=='string'||new TextEncoder().encode(d.content).length>20000||!d.content.startsWith('VOCALVEND DEMO DOCUMENT'))reject('Upload both sample TXT documents using the provided templates.');docs[key]={name:d.name,content:d.content}}return {info,documents:docs,status:'demo_complete',completedAt:new Date().toISOString()}}
if(typeof module!=='undefined')module.exports={validateVerification};
